files.content:
.accordion{
  display:flex;
  flex-direction:column;
  border-radius:var(--r-lg);
  overflow:hidden;
  background:var(--obsidian-950);
}
.acc-item{
  border-bottom:var(--bw-1) solid var(--obsidian-800);
  background:transparent;
  transition:background var(--d-quick) var(--ease-decel);
}
.acc-item:last-child{
  border-bottom:0;
}
.acc-item.is-open{
  background:rgba(240,81,213,0.04);
}
.acc-trigger{
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  align-items:center;
  gap:var(--s-4);
  width:100%;
  min-height:calc(var(--s-12) + var(--s-2));
  padding:var(--s-4) var(--s-6);
  background:transparent;
  border:0;
  color:var(--obsidian-100);
  text-align:left;
  cursor:pointer;
  font:inherit;
  font-size:var(--t-body);
  letter-spacing:var(--tr-snug);
  transition:color var(--d-quick) var(--ease-decel);
}
.acc-trigger:hover{
  color:var(--obsidian-050);
}
.acc-trigger:active{
  color:var(--obsidian-300);
}
.acc-trigger:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--focus-width));
  box-shadow:var(--ring-halo);
}
.acc-chevron{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:16px;
  height:16px;
  flex:0 0 16px;
  color:var(--obsidian-400);
  transition:transform var(--d-base) var(--ease-standard), color var(--d-quick) var(--ease-standard);
}
.acc-chevron svg{
  width:var(--icon-xs);
  height:var(--icon-xs);
  display:block;
}
.acc-item.is-open .acc-chevron{
  transform:rotate(90deg);
  color:var(--primary-400);
  transition:transform var(--d-base) var(--ease-decel), color var(--d-quick) var(--ease-standard);
}
.acc-label{
  min-width:0;
  font-weight:500;
}
.acc-num{
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-500);
  text-transform:uppercase;
  flex-shrink:0;
}
.acc-item.is-open .acc-num{
  color:var(--primary-400);
}
.acc-panel{
  display:grid;
  grid-template-rows:0fr;
  transition:grid-template-rows var(--acc-d, var(--d-slow)) var(--ease-standard);
}
.acc-item.is-open .acc-panel{
  grid-template-rows:1fr;
  transition:grid-template-rows var(--acc-d, var(--d-slow)) var(--ease-decel);
}
.acc-panel-inner{
  overflow:hidden;
  min-height:0;
}
.acc-panel-body{
  padding:0 var(--s-6) var(--s-6) calc(var(--s-4) + var(--s-4) + var(--s-6));
  color:var(--obsidian-300);
  line-height:1.7;
  font-size:var(--t-small);
  opacity:0;
  transition:opacity var(--d-quick) var(--ease-decel) 80ms;
}
.acc-item.is-open .acc-panel-body{
  opacity:1;
}
.acc-panel-body p{
  margin:0 0 var(--s-3);
}
.acc-panel-body p:last-child{
  margin-bottom:0;
}
@media (prefers-reduced-motion: reduce){
  .acc-trigger, .acc-chevron, .acc-panel, .acc-panel-body, .acc-item{
    transition:none;
  }
}
.accordion{
  width:min(100%, calc(var(--s-32) * 2.5));
}
